import{_ as a,o,c as t,a0 as n}from"./chunks/framework.Bogozrur.js";const u=JSON.parse('{"title":"Ecosystem & Examples","description":"","frontmatter":{},"headers":[],"relativePath":"examples/index.md","filePath":"examples/index.md"}'),s={name:"examples/index.md"};function i(r,e,l,c,d,m){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="ecosystem-examples" tabindex="-1">Ecosystem &amp; Examples <a class="header-anchor" href="#ecosystem-examples" aria-label="Permalink to &quot;Ecosystem &amp; Examples&quot;">​</a></h1><p>AAYU&#39;s Intent Engine is capable of scaffolding entirely different business domains dynamically. Below is a showcase of the reference enterprise applications you can build using AAYU with <strong>zero boilerplate code</strong>.</p><h2 id="official-domains-supported" tabindex="-1">Official Domains Supported <a class="header-anchor" href="#official-domains-supported" aria-label="Permalink to &quot;Official Domains Supported&quot;">​</a></h2><h3 id="_1-hospital-management-system" tabindex="-1">1. Hospital Management System <a class="header-anchor" href="#_1-hospital-management-system" aria-label="Permalink to &quot;1. Hospital Management System&quot;">​</a></h3><p>Manage <code>Patient</code>s, schedule <code>Appointment</code>s, and write <code>Prescription</code>s with strict RBAC ensuring only a <code>Doctor</code> can write medical records. <strong>Command</strong>: <code>aayu build &quot;Build a Hospital Management System&quot;</code></p><h3 id="_2-crm-customer-relationship-management" tabindex="-1">2. CRM (Customer Relationship Management) <a class="header-anchor" href="#_2-crm-customer-relationship-management" aria-label="Permalink to &quot;2. CRM (Customer Relationship Management)&quot;">​</a></h3><p>Track your business pipeline seamlessly from <code>Lead</code> to <code>Opportunity</code> to <code>Customer</code>. <strong>Command</strong>: <code>aayu build &quot;Build a CRM&quot;</code></p><h3 id="_3-learning-management-system-lms" tabindex="-1">3. Learning Management System (LMS) <a class="header-anchor" href="#_3-learning-management-system-lms" aria-label="Permalink to &quot;3. Learning Management System (LMS)&quot;">​</a></h3><p>Run a school or university with <code>Student</code>, <code>Instructor</code>, and <code>Course</code> entities mapping natively via Many-to-Many junctions. <strong>Command</strong>: <code>aayu build &quot;Build a Learning Management System&quot;</code></p><h3 id="_4-police-complaint-system" tabindex="-1">4. Police Complaint System <a class="header-anchor" href="#_4-police-complaint-system" aria-label="Permalink to &quot;4. Police Complaint System&quot;">​</a></h3><p>A high-security portal mapping <code>Citizen</code> complaints to <code>Officer</code> investigations using a rigorous State Machine workflow. <strong>Command</strong>: <code>aayu build &quot;Build a Police Complaint System&quot;</code></p><h3 id="_5-e-commerce-platform" tabindex="-1">5. E-Commerce Platform <a class="header-anchor" href="#_5-e-commerce-platform" aria-label="Permalink to &quot;5. E-Commerce Platform&quot;">​</a></h3><p>A robust storefront managing <code>Product</code> catalog, <code>Order</code> processing, and <code>Payment</code> states. <strong>Command</strong>: <code>aayu build &quot;Build an E-Commerce Platform&quot;</code></p><h3 id="_6-hrms-human-resources" tabindex="-1">6. HRMS (Human Resources) <a class="header-anchor" href="#_6-hrms-human-resources" aria-label="Permalink to &quot;6. HRMS (Human Resources)&quot;">​</a></h3><p>Handle internal <code>Employee</code> data, process <code>LeaveRequest</code> workflows, and manage <code>Payroll</code> securely. <strong>Command</strong>: <code>aayu build &quot;Build an HRMS for employee leave and payroll&quot;</code></p><hr><h2 id="exploring-the-output" tabindex="-1">Exploring the Output <a class="header-anchor" href="#exploring-the-output" aria-label="Permalink to &quot;Exploring the Output&quot;">​</a></h2><p>When you run any of the build commands above, you can inspect the generated <code>main.aayu</code> file and the corresponding <code>.html</code> views in your directory.</p><p>We highly recommend exploring the <code>main.aayu</code> file to learn how AAYU natively represents complex systems. All these generated apps will instantly compile into a secure, thread-safe web server when you run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aayu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div>',20)])])}const h=a(s,[["render",i]]);export{u as __pageData,h as default};
